function buildServerRecommendations(m,topBuckets,topTables){const storagePct=serverPercent(m.storage_used_bytes,m.storage_limit_bytes),dbPct=serverPercent(m.database_used_bytes,m.database_limit_bytes),items=[];if(storagePct>=90)items.push(["critical","File Storage kritis",`Hapus/arsipkan foto lama dari bucket ${topBuckets[0]?.bucket||"terbesar"}, terapkan kompresi, atau naikkan paket.`]);else if(storagePct>=75)items.push(["warning","File Storage mendekati batas",`Audit file terbesar di bucket ${topBuckets[0]?.bucket||"Storage"} dan tetapkan retensi foto.`]);else items.push(["good","File Storage masih aman","Pertahankan kompresi foto dan tinjau file tidak terpakai secara berkala."]);if(dbPct>=90)items.push(["critical","Database kritis",`Tabel ${topTables[0]?.table||"terbesar"} perlu ditinjau. Arsipkan data lama, periksa index, dan pertimbangkan upgrade.`]);else if(dbPct>=75)items.push(["warning","Database mendekati batas",`Periksa pertumbuhan tabel ${topTables[0]?.table||"terbesar"}, dead tuples, index yang tidak digunakan, dan jadwal VACUUM.`]);else items.push(["good","Database masih aman","Pantau tren harian dan lakukan VACUUM/ANALYZE sesuai kebutuhan operasi."]);if(Number(m.wal_size_bytes)>Number(m.database_used_bytes)*.3)items.push(["warning","WAL relatif besar","Periksa replication slot, transaksi panjang, dan proses backup/replication yang tertahan."]);if(Number(m.storage_object_count)>10000)items.push(["info","Jumlah file tinggi","Gunakan struktur folder per bulan, kebijakan retensi, dan pembersihan file orphan."]);return items}
function renderServerCharts(history,m){const labels=history.map(x=>new Intl.DateTimeFormat("id-ID",{day:"2-digit",month:"short"}).format(new Date(x.snapshot_date+"T00:00:00"))),gb=n=>Number(n||0)/1073741824;serverHistoryChart?.destroy();serverHistoryChart=new Chart($("#serverHistoryChart"),{type:"line",data:{labels,datasets:[{label:"Storage (GB)",data:history.map(x=>gb(x.storage_used_bytes)),borderColor:"#22d3ee",backgroundColor:"#22d3ee22",fill:true,tension:.3},{label:"Database (GB)",data:history.map(x=>gb(x.database_used_bytes)),borderColor:"#10b981",backgroundColor:"#10b98122",fill:true,tension:.3},{label:"WAL (GB)",data:history.map(x=>gb(x.wal_size_bytes)),borderColor:"#f59e0b",tension:.3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom",labels:{color:"#cbd5e1",usePointStyle:true}}},scales:{x:{ticks:{color:"#94a3b8"},grid:{color:"#33415544"}},y:{beginAtZero:true,title:{display:true,text:"GB",color:"#94a3b8"},ticks:{color:"#94a3b8"},grid:{color:"#33415544"}}}}});serverUsageChart?.destroy();serverUsageChart=new Chart($("#serverUsageChart"),{type:"doughnut",data:{labels:["File Storage","Public Tables","WAL","Database Internal/Other"],datasets:[{data:[gb(m.storage_used_bytes),gb(m.public_tables_bytes),gb(m.wal_size_bytes),Math.max(0,gb(m.database_used_bytes)-gb(m.public_tables_bytes))],backgroundColor:["#22d3ee","#10b981","#f59e0b","#8b5cf6"],borderColor:"#0b1425",borderWidth:4}]},options:{responsive:true,maintainAspectRatio:false,cutout:"62%",plugins:{legend:{position:"bottom",labels:{color:"#cbd5e1",usePointStyle:true,padding:12}},tooltip:{callbacks:{label:c=>`${c.label}: ${Number(c.raw).toFixed(3)} GB`}}}}});icons()}
async function loadServerMetrics(){if(profile?.role!=="admin")return;const btn=$("#refreshServerMetricsBtn"),badge=$("#serverHealthBadge"),errorBox=$("#serverMetricsError");btn.disabled=true;badge.className="server-health loading";badge.innerHTML="<i></i>Memuat";errorBox.classList.add("hidden");try{const{data,error}=await sb.rpc("admin_server_dashboard");if(error)throw error;const result=Array.isArray(data)?data[0]:data,m=result.metrics||result,history=result.history||[],topBuckets=result.top_buckets||[],topTables=result.top_tables||[],disk=Number(m.database_used_bytes||0)+Number(m.wal_size_bytes||0);paintServerCapacity("Storage",Number(m.storage_used_bytes),Number(m.storage_limit_bytes));paintServerCapacity("Database",Number(m.database_used_bytes),Number(m.database_limit_bytes));$("#serverDiskUsed").textContent=formatServerBytes(disk);$("#serverWalSize").textContent=formatServerBytes(m.wal_size_bytes);$("#serverObjectCount").textContent=Number(m.storage_object_count||0).toLocaleString("id-ID");$("#serverBucketCount").textContent=Number(m.bucket_count||0).toLocaleString("id-ID");$("#serverPublicTablesSize").textContent=formatServerBytes(m.public_tables_bytes);$("#serverWorksCount").textContent=Number(m.works_count||0).toLocaleString("id-ID");$("#serverEquipmentCount").textContent=Number(m.equipment_count||0).toLocaleString("id-ID");$("#serverProfilesCount").textContent=Number(m.profiles_count||0).toLocaleString("id-ID");$("#serverMetricsUpdated").textContent=`Diperbarui ${new Intl.DateTimeFormat("id-ID",{dateStyle:"medium",timeStyle:"medium"}).format(new Date(m.measured_at||Date.now()))}`;const storagePct=serverPercent(m.storage_used_bytes,m.storage_limit_bytes),dbPct=serverPercent(m.database_used_bytes,m.database_limit_bytes),peak=Math.max(storagePct,dbPct),warning=$("#serverCapacityWarning");badge.className=`server-health ${peak>=90?"danger":peak>=75?"warning":"healthy"}`;badge.innerHTML=`<i></i>${peak>=90?"Kritis":peak>=75?"Perhatian":"Normal"}`;warning.classList.toggle("hidden",peak<75);if(peak>=75){$("#serverWarningTitle").textContent=peak>=90?"Kapasitas hampir penuh":"Kapasitas mulai tinggi";$("#serverWarningText").textContent=`Penggunaan tertinggi ${peak.toFixed(1)}%. Segera tinjau kontributor terbesar dan jalankan saran tindakan di bawah.`}const contributors=[...topBuckets.slice(0,4).map(x=>({label:`Bucket: ${x.bucket}`,bytes:x.bytes,type:"bucket"})),...topTables.slice(0,4).map(x=>({label:`Table: ${x.table}`,bytes:x.bytes,type:"table"}))].sort((a,b)=>b.bytes-a.bytes).slice(0,6);$("#serverTopContributors").innerHTML=contributors.map(x=>contributorRow(x.label,x.bytes,x.type)).join("")||'<p class="server-empty">Belum ada data kontributor.</p>';$("#serverRecommendations").innerHTML=buildServerRecommendations(m,topBuckets,topTables).map(([level,title,text])=>`<article class="recommendation ${level}"><i data-lucide="${level==="critical"?"circle-alert":level==="warning"?"triangle-alert":level==="good"?"circle-check-big":"info"}"></i><div><strong>${esc(title)}</strong><p>${esc(text)}</p></div></article>`).join("");$("#serverHistoryTable").innerHTML=history.slice().reverse().map(x=>`<tr><td>${new Intl.DateTimeFormat("id-ID",{dateStyle:"medium"}).format(new Date(x.snapshot_date+"T00:00:00"))}</td><td>${formatServerBytes(x.storage_used_bytes)}</td><td>${formatServerBytes(x.database_used_bytes)}</td><td>${formatServerBytes(x.wal_size_bytes)}</td><td>${formatServerBytes(Number(x.database_used_bytes)+Number(x.wal_size_bytes))}</td><td>${Number(x.storage_object_count||0).toLocaleString("id-ID")}</td></tr>`).join("")||'<tr><td colspan="6">Belum ada riwayat.</td></tr>';renderServerCharts(history,m);icons()}catch(err){badge.className="server-health danger";badge.innerHTML="<i></i>Gagal";errorBox.textContent=`Info server gagal dimuat: ${err.message}. Jalankan server_monitoring_setup.sql di Supabase SQL Editor.`;errorBox.classList.remove("hidden");icons()}finally{btn.disabled=false}}
function page(n,b){if(!n)return;if(["manage","users","server"].includes(n)&&profile.role!=="admin")return;$$('.page').forEach(x=>x.classList.add("hidden"));$("#"+n+"Page").classList.remove("hidden");$$("#nav button").forEach(x=>x.classList.remove("active"));b?.classList.add("active");$("#pageTitle").textContent={dashboard:"Dashboard",kpi:"KPI Bulanan",tracker:"Task Tracker",works:"Pekerjaan",manage:"Master Data",users:"Pengguna",server:"Info Server"}[n];if(window.innerWidth<=780){window.scrollTo({top:0,left:0,behavior:"auto"});b?.scrollIntoView({behavior:"smooth",block:"nearest",inline:"center"})}if(n==="kpi")setTimeout(renderMonthlyKpi,0);if(n==="tracker")setTimeout(renderTaskTracker,0);if(n==="server"&&profile.role==="admin")setTimeout(()=>{loadServerMetrics();renderMaintenanceState()},0)}
function setPhotoUploadLog(message,type="info"){const box=$("#photoUploadLog");if(!box)return;box.className=`photo-upload-log ${type}`;const icon=type==="success"?"circle-check-big":type==="error"?"circle-alert":type==="working"?"loader-circle":"info";box.innerHTML=`<i data-lucide="${icon}"></i><span>${esc(message)}</span>`;icons()}
function scheduleWorksRefresh(){clearTimeout(worksRefreshTimer);worksRefreshTimer=setTimeout(()=>{if(session?.user)loadWorks()},250)}
async function setupWorksRealtime(){if(worksRealtimeChannel)await sb.removeChannel(worksRealtimeChannel);worksRealtimeChannel=sb.channel("works-live-activity").on("postgres_changes",{event:"*",schema:"public",table:"works"},scheduleWorksRefresh).subscribe()}
async function loadWorks(){const{data,error}=await sb.from("works").select("*,equipment(*)").order("created_at",{ascending:false});if(error)return toast(error.message,true);works=data||[];tasklistStates.clear();if(works.length){const{data:states,error:stateError}=await sb.from("work_tasklist_state").select("work_id,task_results,draft_photo_path,updated_at").in("work_id",works.map(x=>x.id));if(stateError)console.warn("Tasklist state belum tersedia:",stateError.message);else(states||[]).forEach(row=>tasklistStates.set(row.work_id,row))}works=works.map(work=>({...work,tasklist_state:tasklistStates.get(work.id)||null}));render()}
async function loadEquipment(){const{data,error}=await sb.from("equipment").select("*").order("name");if(error)return toast(error.message,true);equipment=data||[];const selectedArea=$("#areaFilter").value,areas=[...new Set(equipment.map(x=>String(x.area||"").trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"id"));$("#areaFilter").innerHTML='<option value="">Semua area</option>'+areas.map(area=>`<option value="${esc(area)}">${esc(area)}</option>`).join("");if(areas.includes(selectedArea))$("#areaFilter").value=selectedArea;$("#equipmentCodeSelect").innerHTML='<option value="">Pilih Code Number</option>'+equipment.map(x=>`<option value="${x.id}">${esc(x.code_number||"-")} | ${esc(x.plant||"-")} | ${esc(x.area||"-")} | ${esc(x.name)}</option>`).join("");syncWorkEquipment();renderMaster()}
function syncWorkEquipment(){const id=$("#equipmentCodeSelect").value,x=equipment.find(item=>item.id===id);$("#equipmentId").value=x?.id||"";$("#equipmentNameDisplay").value=x?.name||"";$("#equipmentAreaDisplay").value=x?.area||""}
function activityTimestamp(work,mode="works"){const value=mode==="findings"?(work.updated_at||work.completed_at||work.created_at||work.due_date):(work.created_at||work.updated_at||work.due_date);const time=new Date(value||0).getTime();return Number.isFinite(time)?time:0}
function setLiveActivityMode(mode){liveActivityMode=mode==="findings"?"findings":"works";renderLiveActivity()}
function renderLiveActivity(){const findings=works.filter(x=>{const condition=String(x.finding_condition||"").trim().toUpperCase().replace(/[ -]+/g,"_");return condition==="NOT_OK"||String(x.finding_detail||"").trim().length>0}),isFindings=liveActivityMode==="findings",data=(isFindings?findings:works).slice().sort((a,b)=>activityTimestamp(b,isFindings?"findings":"works")-activityTimestamp(a,isFindings?"findings":"works")).slice(0,6);$("#liveActivityTitle").textContent=isFindings?"Temuan Terbaru":"Pekerjaan Terbaru";$("#liveActivityCaption").textContent=isFindings?"Enam temuan terbaru beserta asal pekerjaannya":"Enam pekerjaan terbaru dari seluruh area";$("#latestFindingCount").textContent=findings.length;const worksButton=$("#showLatestWorksBtn"),findingsButton=$("#showLatestFindingsBtn");worksButton.classList.toggle("active",!isFindings);findingsButton.classList.toggle("active",isFindings);worksButton.setAttribute("aria-selected",String(!isFindings));findingsButton.setAttribute("aria-selected",String(isFindings));$("#recentList").innerHTML=data.map((x,i)=>isFindings?`<article class="dashboard-recent-item finding-activity-item"><div class="recent-number finding"><i data-lucide="triangle-alert"></i></div><div class="recent-main"><strong>${esc(x.finding_detail||"Temuan kondisi tidak sesuai")}</strong><div class="finding-source"><span>Ditemukan pada pekerjaan</span><b>${esc(x.title||"-")}</b></div><div class="recent-meta"><span><i data-lucide="factory"></i>${esc(x.equipment?.name||"-")}</span><span class="recent-code"><i data-lucide="scan-line"></i>${esc(x.equipment?.code_number||"-")}</span><span><i data-lucide="user-round"></i>${esc(x.pic||"-")}</span></div></div><div class="recent-right"><span class="finding-condition-badge">Temuan</span><small>${formatWorkDate(x.due_date)}</small></div></article>`:`<article class="dashboard-recent-item"><div class="recent-number">${String(i+1).padStart(2,"0")}</div><div class="recent-main"><strong>${esc(x.title)}</strong><div class="recent-meta"><span><i data-lucide="factory"></i>${esc(x.equipment?.name||"-")}</span><span class="recent-code"><i data-lucide="scan-line"></i>${esc(x.equipment?.code_number||"-")}</span><span><i data-lucide="user-round"></i>${esc(x.pic||"-")}</span></div></div><div class="recent-right"><span class="badge ${x.status}">${x.verified_at?"Terverifikasi":esc(x.status||"-")}</span><small>${formatWorkDate(x.due_date)}</small></div></article>`).join("")||`<p class="dashboard-empty"><i data-lucide="${isFindings?"search-x":"inbox"}"></i>${isFindings?"Belum ada temuan pekerjaan.":"Belum ada pekerjaan."}</p>`;icons()}
function render(){const today=localDateKey(),future=new Date(today+"T00:00:00");future.setDate(future.getDate()+30);const futureKey=localDateKey(future),done=works.filter(x=>x.verified_at),deadlineWorks=dashboardDeadlineWorks(),overdue=deadlineWorks.filter(x=>!isTaskComplete(x)&&String(x.due_date||"").slice(0,10)&&String(x.due_date).slice(0,10)<today),upcoming=deadlineWorks.filter(x=>!isTaskComplete(x)&&String(x.due_date||"").slice(0,10)>=today&&String(x.due_date||"").slice(0,10)<=futureKey),completion=works.length?Math.round(done.length/works.length*100):0;$("#kpiTotal").textContent=works.length;$("#kpiOpen").textContent=works.filter(x=>x.status==="Open").length;$("#kpiProcess").textContent=works.filter(x=>x.status==="Proses"||(x.status==="Selesai"&&!x.verified_at)).length;$("#kpiDone").textContent=done.length;$("#dashboardCompletion").textContent=`${completion}%`;$("#dashboardHealthCaption").textContent=`${done.length} dari ${works.length} pekerjaan selesai`;$("#dashboardHealthRing").style.setProperty("--health",`${completion*3.6}deg`);$("#dashboardOverdue").textContent=overdue.length;$("#dashboardUpcoming").textContent=upcoming.length;renderLiveActivity();renderWorks();if(!$("#kpiPage").classList.contains("hidden"))renderMonthlyKpi();if(!$("#trackerPage").classList.contains("hidden"))renderTaskTracker();icons()}
function filtered(){const q=$("#searchInput").value.toLowerCase(),s=$("#statusFilter").value,p=$("#priorityFilter").value,t=$("#typeFilter").value,area=$("#areaFilter").value,pic=$("#picFilter").value.toLowerCase(),date=$("#dateFilter").value;return works.filter(x=>[x.title,x.description,x.pic,x.equipment?.name,x.equipment?.code_number,x.equipment?.area].join(" ").toLowerCase().includes(q)&&(!s||x.status===s)&&(!p||x.priority===p)&&(!t||x.work_type===t)&&(!area||String(x.equipment?.area||"")===area)&&(!pic||String(x.pic||"").toLowerCase().includes(pic))&&(!date||String(x.due_date||"").slice(0,10)===date))}
function reset(){["searchInput","statusFilter","priorityFilter","typeFilter","areaFilter","picFilter","dateFilter"].forEach(id=>$("#"+id).value="");renderWorks()}
function photo(p){const u=url(p);return u?`<a href="${u}" target="_blank"><img class="photo" src="${u}" alt="Foto"></a>`:""}
function verifyCell(x){if(x.verified_at)return "✓ "+esc(x.verified_by_name||"Terverifikasi");if(canVerifyWork(x)&&x.status==="Selesai"&&x.after_photo_path)return `<button class="mini-btn btn-upload" data-verify="${x.id}"><i data-lucide="signature"></i>Verifikasi</button>`;if(isVerifierRole()&&x.status==="Selesai"&&x.after_photo_path&&!canVerifyWork(x))return `<span class="verification-restricted" title="${esc(verificationAreaMessage())}"><i data-lucide="shield-x"></i>Area dibatasi</span>`;return x.status==="Proses"?"Menunggu teknisi":x.status==="Selesai"?"Menunggu user":"Belum dimulai"}
function actions(x){const a=[`<button class="mini-btn" data-detail="${x.id}"><i data-lucide="eye"></i>Detail</button>`];if(profile.role==="admin")a.push(`<button class="mini-btn" data-edit="${x.id}"><i data-lucide="pencil"></i>Edit</button><button class="mini-btn btn-danger" data-delete="${x.id}"><i data-lucide="trash-2"></i>Hapus</button>`);if(profile.role==="technician"&&x.status==="Open"&&canTechnicianStart(x))a.push(`<button class="mini-btn btn-start" data-start="${x.id}"><i data-lucide="play"></i>Mulai</button>`);if(profile.role==="technician"&&x.status==="Proses"&&canTechnicianComplete(x))a.push(`<button class="mini-btn btn-upload" data-photo="${x.id}"><i data-lucide="camera"></i>Foto</button>`);return `<div class="action-group">${a.join("")}</div>`}
function formatWorkDate(value){if(!value)return "-";const raw=String(value).slice(0,10),parts=raw.split("-");if(parts.length!==3)return "-";const date=new Date(Number(parts[0]),Number(parts[1])-1,Number(parts[2]));return Number.isNaN(date.getTime())?"-":new Intl.DateTimeFormat("id-ID",{day:"2-digit",month:"short",year:"numeric"}).format(date)}
function workMonthKey(x){return String(x.due_date||x.created_at||"").slice(0,7)||"tanpa-tanggal"}
function workMonthLabel(key){if(key==="tanpa-tanggal")return "Tanpa Tanggal";const [year,month]=key.split("-");return new Intl.DateTimeFormat("id-ID",{month:"long",year:"numeric"}).format(new Date(Number(year),Number(month)-1,1))}
function renderWorks(){const data=filtered().slice().sort((a,b)=>workMonthKey(b).localeCompare(workMonthKey(a))||String(b.due_date||"").localeCompare(String(a.due_date||""))||String(b.created_at||"").localeCompare(String(a.created_at||""))||String(a.id||"").localeCompare(String(b.id||"")));let lastMonth="";$("#workTable").innerHTML=data.map((x,i)=>{const month=workMonthKey(x),group=month!==lastMonth?`<tr class="month-group"><td colspan="14"><i data-lucide="calendar-days"></i>${esc(workMonthLabel(month))}</td></tr>`:"";lastMonth=month;return group+`<tr><td class="select-col mass-delete-col"><input class="work-select" type="checkbox" value="${x.id}" data-verify-eligible="${x.status==="Selesai"&&x.after_photo_path&&!x.verified_at&&canVerifyWork(x)?"true":"false"}" aria-label="Pilih pekerjaan"></td><td>${i+1}</td><td class="work-title-cell"><strong>${esc(x.title)}</strong></td><td class="date-cell">${formatWorkDate(x.due_date)}</td><td>${esc(x.equipment?.name||"-")}</td><td class="code-number-cell">${esc(x.equipment?.code_number||"-")}</td><td class="area-cell">${esc(x.equipment?.area||"-")}</td><td>${esc(x.work_type||"-")}</td><td>${esc(x.priority||"-")}</td><td>${esc(x.pic||"-")}</td><td><span class="badge ${x.status}">${x.verified_at?"Terverifikasi":esc(x.status||"-")}</span></td><td>${photo(x.before_photo_path)} ${photo(x.after_photo_path)}</td><td>${verifyCell(x)}</td><td>${actions(x)}</td></tr>`}).join("")||'<tr><td colspan="14">Data tidak ditemukan</td></tr>';icons();syncWorkSelection()}
function setMassDeleteMode(type,enabled){const work=type==="works",table=$(work?"#worksTableView":"#equipmentTableView"),start=$(work?"#massDeleteWorksBtn":"#massDeleteEquipmentBtn"),remove=$(work?"#deleteSelectedWorksBtn":"#deleteSelectedEquipmentBtn"),cancel=$(work?"#cancelMassDeleteWorksBtn":"#cancelMassDeleteEquipmentBtn"),all=$(work?"#selectAllWorks":"#selectAllEquipment");table.classList.toggle("mass-delete-mode",enabled);table.classList.toggle("mass-delete-off",!enabled);start.classList.toggle("hidden",enabled);remove.classList.toggle("hidden",!enabled);cancel.classList.toggle("hidden",!enabled);all.checked=false;all.indeterminate=false;if(work){$$('.work-select').forEach(x=>x.checked=false);syncWorkSelection()}else{$$('.equipment-select').forEach(x=>x.checked=false);syncEquipmentSelection()}icons()}
function selectedWorkIds(){return $$('.work-select:checked').map(x=>x.value)}
function eligibleVerificationIds(){return selectedWorkIds().filter(id=>{const x=works.find(w=>w.id===id);return x&&x.status==="Selesai"&&x.after_photo_path&&!x.verified_at&&canVerifyWork(x)})}
function syncWorkSelection(){const verifyMode=$("#worksTableView").classList.contains("mass-verify-mode"),all=verifyMode?$$('.work-select[data-verify-eligible="true"]'):$$('.work-select'),checked=selectedWorkIds(),eligible=eligibleVerificationIds();$('#deleteSelectedWorksBtn').disabled=!checked.length;$('#verifySelectedWorksBtn').disabled=!eligible.length;$('#verifySelectedWorksBtn').querySelector('span').textContent=eligible.length?`Verifikasi Terpilih (${eligible.length})`:'Verifikasi Terpilih';$('#selectAllWorks').checked=!!all.length&&checked.length===all.length;$('#selectAllWorks').indeterminate=checked.length>0&&checked.length<all.length}
function setMassVerifyMode(enabled){if(!isVerifierRole())return;const table=$("#worksTableView"),massDeleteBtn=$("#massDeleteWorksBtn");if(enabled)setMassDeleteMode("works",false);table.classList.toggle("mass-verify-mode",enabled);table.classList.toggle("mass-delete-off",!enabled&&!table.classList.contains("mass-delete-mode"));$("#massVerifyWorksBtn").classList.toggle("hidden",enabled);$("#verifySelectedWorksBtn").classList.toggle("hidden",!enabled);$("#cancelMassVerifyWorksBtn").classList.toggle("hidden",!enabled);if(massDeleteBtn)massDeleteBtn.classList.toggle("hidden",enabled||profile?.role!=="admin");$$('.work-select').forEach(x=>x.checked=false);$('#selectAllWorks').checked=false;$('#selectAllWorks').indeterminate=false;syncWorkSelection();icons()}
function openMassVerify(){const ids=eligibleVerificationIds();if(!ids.length)return toast("Pilih pekerjaan selesai yang memiliki foto sesudah dan belum diverifikasi",true);verifyIds=ids;verifyId=null;clearSign();const selected=works.filter(x=>ids.includes(x.id));$("#signatureModalTitle").textContent=`Mass Verification (${ids.length})`;$("#signatureWorkSummary").classList.remove("hidden");$("#signatureWorkSummary").innerHTML=selected.map((x,i)=>`<span><b>${i+1}.</b> ${esc(x.title)} <small>${esc(x.pic||"-")} • ${esc(x.equipment?.code_number||"-")}</small></span>`).join("");$("#signatureModal").classList.remove("hidden");icons()}
function closeSignatureModal(){verifyId=null;verifyIds=[];$("#signatureModal").classList.add("hidden");$("#signatureWorkSummary").classList.add("hidden");$("#signatureWorkSummary").innerHTML="";$("#signatureModalTitle").textContent="Paraf Verifikasi";clearSign()}

function toggleAllWorks(e){const verifyMode=$("#worksTableView").classList.contains("mass-verify-mode"),items=verifyMode?$$('.work-select[data-verify-eligible="true"]'):$$('.work-select');items.forEach(x=>x.checked=e.target.checked);syncWorkSelection()}
let pendingDeleteAction=null;
function showDeletePreview(title,items,action){$("#deletePreviewTitle").textContent=title;$("#deletePreviewSummary").textContent=`${items.length} data dipilih. Periksa daftar berikut sebelum melanjutkan.`;$("#deletePreviewList").innerHTML=items.map((x,i)=>`<article class="preview-row"><strong>${i+1}. ${esc(x.title)}</strong><small>${esc(x.meta||"")}</small></article>`).join("");pendingDeleteAction=action;$("#deletePreviewModal").classList.remove("hidden");icons()}
function showOperationLog(title,entries){const success=entries.filter(x=>x.status==="success").length,failed=entries.filter(x=>x.status==="failed").length,rollback=entries.filter(x=>x.status==="rollback").length;$("#operationLogTitle").textContent=title;$("#operationLogSummary").innerHTML=`<span class="log-chip success">Berhasil: ${success}</span><span class="log-chip failed">Gagal: ${failed}</span>${rollback?`<span class="log-chip rollback">Rollback: ${rollback}</span>`:""}`;$("#operationLogList").innerHTML=entries.map(x=>`<article class="log-row ${x.status}"><strong>${esc(x.label)}</strong><small>${esc(x.message)}</small></article>`).join("");$("#operationLogModal").classList.remove("hidden");icons()}
function workStorageReferencePaths(work){return [...new Set([work?.before_photo_path,work?.after_photo_path,work?.signature_path,work?.verification_signature_path,work?.verified_signature_path].filter(path=>typeof path==="string"&&path.trim()).map(path=>path.trim()))]}
async function listWorkFolderPaths(workId){const paths=[];let offset=0;const limit=100;while(true){const{data,error}=await sb.storage.from(C.PHOTO_BUCKET).list(String(workId),{limit,offset,sortBy:{column:"name",order:"asc"}});if(error)throw error;const rows=data||[];for(const item of rows){if(item?.name&&item.id)paths.push(`${workId}/${item.name}`)}if(rows.length<limit)break;offset+=limit}return paths}
