function downloadEquipmentTemplate(){downloadTemplate([{"Equipment":"Nama Equipment","Plant":"Mojokerto","Area":"Milling","Code Number":"EQ-001","Funloc":"AREA-01"}],"template-mass-upload-equipment.xlsx")}
function downloadEquipmentUpdateTemplate(){if(!equipment.length)return toast("Belum ada equipment untuk dibuatkan template update",true);downloadTemplate(equipment.map(x=>({"ID":x.id,"Equipment":x.name||"","Plant":x.plant||"","Area":x.area||"","Code Number":x.code_number||"","Funloc":x.funloc||""})),"template-update-mass-equipment.xlsx")}
async function deleteEquipment(id){if(profile?.role!=="admin")return;const item=equipment.find(x=>x.id===id);if(!item)return;showDeletePreview("Pratinjau Hapus Equipment",[{title:item.name,meta:`${item.code_number||"-"} | ${item.plant||"-"} | ${item.area||"-"}`}],async()=>{const{error}=await sb.from("equipment").delete().eq("id",id);const logs=[{status:error?"failed":"success",label:item.name,message:error?(error.code==="23503"?"Equipment masih digunakan pada pekerjaan":error.message):"Equipment berhasil dihapus"}];showOperationLog("Log Penghapusan Equipment",logs);await loadEquipment();await loadWorks()})}
async function deleteUser(id,email){if(profile?.role!=="admin")return;if(id===session.user.id)return toast("Akun admin yang sedang digunakan tidak dapat dihapus",true);if(!confirm(`Hapus pengguna ${email}? Akun Auth dan profil pengguna akan dihapus.`))return;try{const{data,error}=await sb.functions.invoke("admin-user",{body:{action:"delete",user_id:id}});if(error)throw error;if(data?.error)throw Error(data.error);toast(data?.message||"Pengguna berhasil dihapus");await loadUsers()}catch(error){toast("Gagal menghapus pengguna: "+error.message,true)}}
function openEquipmentForm(x){if(profile?.role!=="admin")return;$("#equipmentModalTitle").textContent=x?"Edit Equipment":"Tambah Equipment";$("#equipmentEditId").value=x?.id||"";$("#equipmentName").value=x?.name||"";$("#equipmentPlant").value=x?.plant||"";$("#equipmentArea").value=x?.area||"";$("#equipmentCode").value=x?.code_number||"";$("#equipmentFunloc").value=x?.funloc||"";$("#equipmentModal").classList.remove("hidden");icons()}
