function reportDataByRange(start,end){if(!start||!end)throw Error("Tanggal mulai dan akhir wajib dipilih");if(start>end)throw Error("Tanggal mulai tidak boleh setelah tanggal akhir");return filtered().filter(x=>{const d=String(x.due_date||"").slice(0,10);return d&&d>=start&&d<=end})}
function handleExportRange(e){e.preventDefault();const start=$("#exportStartDate").value,end=$("#exportEndDate").value,action=$("#exportAction").value;try{const data=reportDataByRange(start,end);if(!data.length)throw Error("Tidak ada pekerjaan pada range tanggal tersebut");$("#exportRangeModal").classList.add("hidden");if(action==="email"){openEmailModal(start,end)}else exportXlsx(false,start,end)}catch(err){toast(err.message,true)}}
function openEmailModal(start,end){if(!start||!end)return openExportRangeModal("email");$("#reportRecipient").value=C.REPORT_RECIPIENT||"";$("#emailForm").dataset.start=start;$("#emailForm").dataset.end=end;$("#emailModal").classList.remove("hidden");icons()}
function compareCodeNumber(a,b){return String(a.code_number||"").localeCompare(String(b.code_number||""),"id",{numeric:true,sensitivity:"base"})}
function toggleEquipmentCodeSort(){equipmentCodeSort=equipmentCodeSort==="asc"?"desc":"asc";const button=$("#sortEquipmentCodeBtn");button.innerHTML=equipmentCodeSort==="asc"?'<i data-lucide="arrow-down-a-z"></i><span>Code A-Z</span>':'<i data-lucide="arrow-up-z-a"></i><span>Code Z-A</span>';button.title=equipmentCodeSort==="asc"?"Urutkan Code Number ascending":"Urutkan Code Number descending";renderMaster();icons()}
function renderMaster(){const sorted=equipment.slice().sort((a,b)=>equipmentCodeSort==="asc"?compareCodeNumber(a,b):compareCodeNumber(b,a));$("#masterTable").innerHTML=sorted.map(x=>`<tr><td class="select-col mass-delete-col"><input class="equipment-select" type="checkbox" value="${x.id}" aria-label="Pilih equipment"></td><td>${esc(x.name)}</td><td>${esc(x.plant||"-")}</td><td>${esc(x.area||"-")}</td><td>${esc(x.code_number||"-")}</td><td>${esc(x.funloc||"-")}</td><td><div class="row-actions"><button class="mini-btn" data-master="${x.id}">Edit</button><button class="mini-btn danger" data-delete-equipment="${x.id}">Hapus</button></div></td></tr>`).join("");$$('[data-master]').forEach(b=>b.onclick=()=>openEquipmentForm(equipment.find(x=>x.id===b.dataset.master)));$$('[data-delete-equipment]').forEach(b=>b.onclick=()=>deleteEquipment(b.dataset.deleteEquipment));$$('.equipment-select').forEach(x=>x.onchange=syncEquipmentSelection);syncEquipmentSelection()}
function selectedEquipmentIds(){return $$('.equipment-select:checked').map(x=>x.value)}
function syncEquipmentSelection(){const all=$$('.equipment-select'),checked=selectedEquipmentIds();$('#deleteSelectedEquipmentBtn').disabled=!checked.length;$('#selectAllEquipment').checked=!!all.length&&checked.length===all.length;$('#selectAllEquipment').indeterminate=checked.length>0&&checked.length<all.length}
function toggleAllEquipment(e){$$('.equipment-select').forEach(x=>x.checked=e.target.checked);syncEquipmentSelection()}
async function deleteSelectedEquipment(){const ids=selectedEquipmentIds();if(!ids.length)return;const selected=equipment.filter(x=>ids.includes(x.id));showDeletePreview("Pratinjau Hapus Equipment",selected.map(x=>({title:x.name,meta:`${x.code_number||"-"} | ${x.plant||"-"} | ${x.area||"-"}`})),async()=>{const logs=[];for(const item of selected){const{error}=await sb.from("equipment").delete().eq("id",item.id);logs.push({status:error?"failed":"success",label:item.name,message:error?(error.code==="23503"?"Masih digunakan pada pekerjaan":error.message):"Equipment berhasil dihapus"})}showOperationLog("Log Penghapusan Massal Equipment",logs);setMassDeleteMode("equipment",false);await loadEquipment();await loadWorks()})}
async function loadUsers(){const{data,error}=await sb.from("profiles").select("*");if(error)return toast(error.message,true);$("#userTable").innerHTML=(data||[]).map(x=>`<tr><td>${esc(x.full_name)}</td><td>${esc(x.email)}</td><td>${esc(x.role)}</td><td>${x.is_active?"Aktif":"Nonaktif"}</td><td><button class="mini-btn danger" data-delete-user="${x.id}" data-user-email="${esc(x.email)}" ${x.id===session.user.id?"disabled":""}>Hapus</button></td></tr>`).join("");$$('[data-delete-user]').forEach(b=>b.onclick=()=>deleteUser(b.dataset.deleteUser,b.dataset.userEmail))}
function readExcel(file){return new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>{try{const wb=XLSX.read(r.result,{type:"array"});resolve(XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:""}))}catch(e){reject(e)}};r.onerror=()=>reject(Error("File gagal dibaca"));r.readAsArrayBuffer(file)})}
async function readWorkExcel(file){const arrayBuffer=await file.arrayBuffer(),sheetBook=XLSX.read(arrayBuffer,{type:"array",cellDates:false}),sheet=sheetBook.Sheets[sheetBook.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{defval:"",raw:false}),excelBook=new ExcelJS.Workbook();await excelBook.xlsx.load(arrayBuffer);const worksheet=excelBook.worksheets[0],imagesByRow=new Map();for(const placed of worksheet.getImages()){const image=excelBook.getImage(placed.imageId),tl=placed.range?.tl||{},zeroBasedRow=Number.isFinite(tl.nativeRow)?tl.nativeRow:Math.floor(Number(tl.row||0)),excelRow=zeroBasedRow+1;if(excelRow<2||!image?.buffer)continue;const extension=String(image.extension||"jpeg").toLowerCase().replace("jpg","jpeg"),mime=extension==="png"?"image/png":extension==="gif"?"image/gif":"image/jpeg",blob=new Blob([image.buffer],{type:mime});if(!imagesByRow.has(excelRow))imagesByRow.set(excelRow,blob)}return{rows,imagesByRow}}
async function uploadEmbeddedBeforePhoto(blob,workId){if(!blob)return null;const ext=blob.type==="image/png"?"png":"jpg",file=new File([blob],`before-${workId}.${ext}`,{type:blob.type||"image/jpeg",lastModified:Date.now()});return upload(file,workId,"before")}
function normalizeExcelHeader(value){return String(value||"").toLowerCase().replace(/[\r\n]+/g," ").replace(/[_\-/()]+/g," ").replace(/[^a-z0-9 ]/g," ").replace(/\s+/g," ").trim()}
const val=(row,names)=>{const aliases=names.map(normalizeExcelHeader),keys=Object.keys(row),exact=keys.find(key=>aliases.includes(normalizeExcelHeader(key)));if(exact)return row[exact];const prefixed=keys.find(key=>{const normalized=normalizeExcelHeader(key);return aliases.some(alias=>normalized.startsWith(alias+" ")||alias.startsWith(normalized+" "))});return prefixed?row[prefixed]:""};
function excelDescriptionValue(row){return String(val(row,["deskripsi","description","deskripsi tasklist","description tasklist","tasklist","task list","checklist pekerjaan"])||"").replace(/\r\n?/g,"\n").trim()}
async function importWorks(e){const file=e.target.files[0];if(!file)return;try{toast("Membaca data dan foto dari Excel...");const{rows,imagesByRow}=await readWorkExcel(file),payload=[],invalid=[];for(let index=0;index<rows.length;index++){const excelRow=index+2,r=rows[index],code=String(val(r,["code number","code_number","kode"])).trim(),plant=String(val(r,["plant"])).trim(),area=String(val(r,["area"])).trim(),equipmentName=String(val(r,["equipment","nama equipment"])).trim(),title=String(val(r,["pekerjaan","judul","title"])).trim(),dueDate=String(val(r,["tanggal","date","due date"])).trim(),imageBlob=imagesByRow.get(excelRow);let matches=[];if(code)matches=equipment.filter(x=>String(x.code_number||"").trim().toLowerCase()===code.toLowerCase());if(plant&&matches.length)matches=matches.filter(x=>String(x.plant||"").trim().toLowerCase()===plant.toLowerCase());if(area&&matches.length)matches=matches.filter(x=>String(x.area||"").trim().toLowerCase()===area.toLowerCase());let eq=matches.length===1?matches[0]:null;if(!eq&&equipmentName)eq=equipment.find(x=>String(x.name||"").trim().toLowerCase()===equipmentName.toLowerCase()&&(!plant||String(x.plant||"").trim().toLowerCase()===plant.toLowerCase())&&(!area||String(x.area||"").trim().toLowerCase()===area.toLowerCase()));const reasons=[];if(!eq)reasons.push("equipment tidak cocok");if(!title)reasons.push("pekerjaan kosong");if(!dueDate)reasons.push("tanggal kosong");if(!imageBlob)reasons.push("foto sebelum tidak ditemukan");if(reasons.length){invalid.push(`${excelRow} (${reasons.join(", ")})`);continue}const id=crypto.randomUUID(),beforePath=await uploadEmbeddedBeforePhoto(imageBlob,id);payload.push({id,title,equipment_id:eq.id,work_type:String(val(r,["jenis","work type"])).trim()||"Others",priority:String(val(r,["prioritas","priority"])).trim()||"Medium",pic:ALLOWED_PICS.includes(String(val(r,["pic"])).trim())?String(val(r,["pic"])).trim():"",status:String(val(r,["status"])).trim()||"Open",description:excelDescriptionValue(r),due_date:dueDate,before_photo_path:beforePath,created_by:session.user.id})}if(!payload.length)throw Error(`Tidak ada baris valid. Tanggal dan foto sebelum wajib diisi. ${invalid.length?`Periksa baris: ${invalid.join("; ")}`:""}`);const{error}=await sb.from("works").insert(payload);if(error)throw error;const tasklistRows=payload.filter(item=>descriptionToTasks(item.description).length>0).length,emptyDescriptions=payload.length-tasklistRows;toast(`${payload.length} pekerjaan berhasil diupload. ${tasklistRows} deskripsi berhasil dikonversi menjadi tasklist${emptyDescriptions?`, ${emptyDescriptions} baris tanpa deskripsi/tasklist`:""}${invalid.length?`; dilewati: ${invalid.join("; ")}`:""}`);loadWorks()}catch(err){toast(err.message,true)}finally{e.target.value=""}}
async function updateEquipmentMass(e){const file=e.target.files[0];if(!file)return;const logs=[],applied=[],snapshots=[];try{const rows=await readExcel(file),updates=[];for(let i=0;i<rows.length;i++){const r=rows[i],id=String(val(r,["id"])).trim(),code=String(val(r,["code number","code_number","kode"])).trim(),plant=String(val(r,["plant"])).trim();let current=id?equipment.find(x=>String(x.id)===id):null;if(!current&&code&&plant)current=equipment.find(x=>String(x.code_number||"").trim().toLowerCase()===code.toLowerCase()&&String(x.plant||"").trim().toLowerCase()===plant.toLowerCase());if(!current){logs.push({status:"failed",label:`Baris ${i+2}`,message:"Equipment terdaftar tidak ditemukan"});continue}snapshots.push({id:current.id,name:current.name,plant:current.plant,area:current.area,code_number:current.code_number,funloc:current.funloc});updates.push({id:current.id,name:String(val(r,["equipment","name","nama equipment"])).trim()||current.name,plant:plant||current.plant,area:String(val(r,["area"])).trim()||current.area,code_number:code||current.code_number,funloc:String(val(r,["funloc","functional location"])).trim()||current.funloc})}if(!updates.length)throw Error("Tidak ada equipment terdaftar yang cocok untuk diperbarui");for(const update of updates){const{error}=await sb.from("equipment").update({name:update.name,plant:update.plant,area:update.area,code_number:update.code_number,funloc:update.funloc}).eq("id",update.id);if(error)throw Object.assign(Error(error.message),{failedUpdate:update});applied.push(update.id);logs.push({status:"success",label:update.name,message:"Equipment berhasil diperbarui"})}toast(`${applied.length} equipment berhasil diperbarui`);showOperationLog("Log Mass Update Equipment",logs);await loadEquipment()}catch(error){if(applied.length){const restore=snapshots.filter(x=>applied.includes(x.id));for(const old of restore){const{error:rollbackError}=await sb.from("equipment").update({name:old.name,plant:old.plant,area:old.area,code_number:old.code_number,funloc:old.funloc}).eq("id",old.id);logs.push({status:rollbackError?"failed":"rollback",label:old.name,message:rollbackError?`Rollback gagal: ${rollbackError.message}`:"Perubahan dikembalikan ke data sebelum update"})}}logs.push({status:"failed",label:error.failedUpdate?.name||"Mass update",message:error.message});showOperationLog("Mass Update Gagal dan Rollback Dijalankan",logs);toast("Mass update gagal. Perubahan yang sempat diterapkan sudah dicoba dikembalikan.",true);await loadEquipment()}finally{e.target.value=""}}
async function importEquipment(e){const file=e.target.files[0];if(!file)return;try{const rows=await readExcel(file),payload=rows.map(r=>({name:String(val(r,["equipment","name","nama equipment"])).trim(),plant:String(val(r,["plant"])).trim(),area:String(val(r,["area"])).trim(),code_number:String(val(r,["code number","code_number","kode"])).trim(),funloc:String(val(r,["funloc","functional location"])).trim()})).filter(x=>x.name);if(!payload.length)throw Error("Tidak ada equipment valid");const{error}=await sb.from("equipment").upsert(payload);if(error)throw error;toast(`${payload.length} equipment berhasil diupload`);loadEquipment()}catch(err){toast(err.message,true)}finally{e.target.value=""}}
async function getPhotoBlob(p){try{const u=url(p);if(u){const r=await fetch(u,{cache:"no-store"});if(r.ok)return r.blob()}}catch{}const{data,error}=await sb.storage.from(C.PHOTO_BUCKET).download(p);if(error)throw error;return data}
async function addPhoto(wb,ws,p,col,row){if(!p)return;try{const blob=await getPhotoBlob(p),img=await createImageBitmap(blob),maxWidth=480,maxHeight=360,scale=Math.min(1,maxWidth/img.width,maxHeight/img.height),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const context=canvas.getContext("2d",{alpha:false});context.fillStyle="#fff";context.fillRect(0,0,canvas.width,canvas.height);context.imageSmoothingEnabled=true;context.imageSmoothingQuality="medium";context.drawImage(img,0,0,canvas.width,canvas.height);img.close?.();const compressed=await new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(Error("Kompresi foto Excel gagal")),"image/jpeg",.42)),id=wb.addImage({buffer:await compressed.arrayBuffer(),extension:"jpeg"});ws.addImage(id,{tl:{col:col-1+.12,row:row-1+.1},ext:{width:120,height:82}})}catch(e){console.error("Foto Excel gagal",p,e)}}
function exportTasklistText(work){const results=normalizedTaskResults(work);if(!results.length)return "Tidak ada tasklist";return results.map((result,index)=>{const status=result.status==="done"?"✓":result.status==="not_done"?"Tidak":"Belum";return `${index+1}. ${status} - ${result.task}`}).join("\n")}
async function exportXlsx(ret=false,start="",end=""){try{const data=start&&end?reportDataByRange(start,end):filtered();if(!data.length)throw Error("Tidak ada data");toast("Membuat XLSX...");const wb=new ExcelJS.Workbook(),ws=wb.addWorksheet("Report");ws.columns=[{header:"No",key:"no",width:7},{header:"Pekerjaan",key:"title",width:32},{header:"Tanggal",key:"date",width:17},{header:"Tanggal Dikerjakan",key:"workedDate",width:20},{header:"Detail Pekerjaan",key:"detail",width:42},{header:"Tasklist",key:"tasklist",width:52},{header:"Equipment",key:"eq",width:24},{header:"Code Number",key:"code",width:18},{header:"Area",key:"area",width:18},{header:"Jenis",key:"type",width:26},{header:"Prioritas",key:"prio",width:14},{header:"PIC",key:"pic",width:19},{header:"Status",key:"status",width:20},{header:"Kondisi Temuan",key:"findingCondition",width:20},{header:"Detail Temuan",key:"findingDetail",width:42},{header:"Foto Sebelum",key:"before",width:19},{header:"Foto Sesudah",key:"after",width:19},{header:"Verifikasi",key:"verify",width:24}];const h=ws.getRow(1);h.font={bold:true,color:{argb:"FFFFFFFF"}};h.fill={type:"pattern",pattern:"solid",fgColor:{argb:"FF2563EB"}};for(let i=0;i<data.length;i++){const x=data[i],r=ws.addRow({no:i+1,title:x.title,date:formatWorkDate(x.due_date),workedDate:x.completed_at?formatWorkDate(x.completed_at):"Belum dikerjakan",detail:x.description||"-",tasklist:exportTasklistText(x),eq:x.equipment?.name,code:x.equipment?.code_number||"-",area:x.equipment?.area||"-",type:x.work_type,prio:x.priority,pic:x.pic,status:x.verified_at?"Terverifikasi":x.status,findingCondition:x.finding_condition==="OK"?"Kondisi OK":x.finding_condition==="NOT_OK"?"Kondisi Tidak OK":"Belum diisi",findingDetail:x.finding_detail||"-",before:x.before_photo_path?"":"Tidak ada",after:x.after_photo_path?"":"Tidak ada",verify:x.verified_at?`Diverifikasi oleh ${x.verified_by_name||"Pengguna"}`:"Belum diverifikasi"});const taskCount=normalizedTaskResults(x).length;r.height=Math.max(72,taskCount*18+18);r.getCell("detail").alignment={vertical:"top",wrapText:true};r.getCell("tasklist").alignment={vertical:"top",wrapText:true};r.getCell("findingDetail").alignment={vertical:"top",wrapText:true};await addPhoto(wb,ws,x.before_photo_path,16,i+2);await addPhoto(wb,ws,x.after_photo_path,17,i+2)}ws.views=[{state:"frozen",ySplit:1}];const buf=await wb.xlsx.writeBuffer(),blob=new Blob([buf],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});if(ret)return blob;const name=start&&end?`maintenance-report-${start}-sd-${end}.xlsx`:reportFileName();saveAs(blob,name);toast("XLSX berhasil dibuat");return blob}catch(e){toast(e.message,true);return null}}
async function sendEmail(e){e.preventDefault();const to=$("#reportRecipient").value.trim(),b=$("#emailSendBtn");if(!to)return;b.disabled=true;b.textContent="Membuat laporan...";try{const start=e.currentTarget.dataset.start||"",end=e.currentTarget.dataset.end||"",blob=await exportXlsx(true,start,end);if(!blob)throw Error("XLSX gagal dibuat");const base64=await new Promise((r,j)=>{const f=new FileReader;f.onload=()=>r(String(f.result).split(",")[1]);f.onerror=j;f.readAsDataURL(blob)}),{data,error}=await sb.functions.invoke("send-report",{body:{to,filename:reportFileName(),attachmentBase64:base64}});if(error)throw error;if(!data?.success)throw Error(data?.error||"Email gagal");$("#emailModal").classList.add("hidden");toast(data.message||"Email berhasil dikirim")}catch(e){toast("Email gagal: "+e.message,true)}finally{b.disabled=false;b.innerHTML='<i data-lucide="send"></i>Buat dan Kirim';icons()}}
init().catch(e=>toast("Aplikasi gagal: "+e.message,true));
